//! Hit testing parity (ex-507).
//!
//! `tests/fixtures/collision.json` is upstream's own
//! `packages/element/src/collision.ts` and `distance.ts` at the pinned
//! commit, generated by `tools/goldens/collision-fixtures.mjs`: the scenes
//! of `packages/element/tests/collision.test.tsx` (`upstream-*`) and seeded
//! random scenes of every element type, each with what upstream answered.
//! Every case is reproduced: `hitElementItself`, `distanceToElement`,
//! `isPointInElement`, `shouldTestInside`, `hitElementBoundingBox`,
//! `hitElementBoundText`, `hitElementBoundingBoxOnly`,
//! `intersectElementWithLineSegment`, `getHoveredElementForBinding`,
//! `getAllHoveredElementAtPoint` and `isBindableElementInsideOtherBindable`.
//!
//! The tests after the replay port `collision.test.tsx`'s assertions one by
//! one on those scenes, including the result cache's (upstream spies on
//! `distanceToElement`; the port's cache counts the outline tests it runs),
//! and pin `App.getElementHitThreshold` (`App.tsx:6927-6934`).

use std::collections::HashSet;

use excali_core::constants::DEFAULT_COLLISION_THRESHOLD;
use excali_core::element::Element;
use excali_editor::collision::{
    get_all_hovered_element_at_point, get_element_hit_threshold, get_hovered_element_for_binding,
    hit_element_bound_text, hit_element_bounding_box, hit_element_bounding_box_only,
    hit_element_itself, intersect_element_with_line_segment, is_bindable_element_inside_other_bindable,
    is_point_in_element, should_test_inside, FrameNameBounds, HitTestArgs, HitTestCache,
};
use excali_editor::distance::distance_to_element;
use excali_scene::bounds::{get_element_bounds, ElementsMap};
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/collision.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("collision.json parses")
}

fn cases() -> Vec<Value> {
    fixture()["cases"].as_array().expect("cases").clone()
}

fn case(id: &str) -> Value {
    cases()
        .into_iter()
        .find(|c| c["id"] == id)
        .unwrap_or_else(|| panic!("no case {id}"))
}

fn elements(case: &Value) -> Vec<Element> {
    case["elements"]
        .as_array()
        .expect("elements")
        .iter()
        .map(|e| Element::from_map(e.as_object().expect("an element").clone()).expect("an element upstream built"))
        .collect()
}

fn point(value: &Value) -> [f64; 2] {
    [
        value[0].as_f64().expect("x"),
        value[1].as_f64().expect("y"),
    ]
}

fn number(value: &Value) -> f64 {
    match value {
        Value::String(s) if s == "Infinity" => f64::INFINITY,
        Value::String(s) if s == "-Infinity" => f64::NEG_INFINITY,
        Value::String(s) if s == "NaN" => f64::NAN,
        v => v.as_f64().expect("a number"),
    }
}

fn frame_name_bound(value: &Value) -> Option<FrameNameBounds> {
    value.as_object().map(|b| FrameNameBounds {
        x: b["x"].as_f64().expect("x"),
        y: b["y"].as_f64().expect("y"),
        width: b["width"].as_f64().expect("width"),
        height: b["height"].as_f64().expect("height"),
    })
}

fn by_id<'a>(elements: &'a [Element], id: &str) -> &'a Element {
    elements
        .iter()
        .find(|e| e.base.id == id)
        .unwrap_or_else(|| panic!("no element {id}"))
}

/// Distances within a few ulps: the curve distances iterate to a
/// tolerance, and the port reproduces their arithmetic, so anything more
/// than rounding noise is a real difference.
fn same_distance(a: f64, b: f64) -> bool {
    if a.is_infinite() || b.is_infinite() || a.is_nan() || b.is_nan() {
        return a == b || (a.is_nan() && b.is_nan());
    }
    (a - b).abs() <= 1e-9 * a.abs().max(b.abs()).max(1.0)
}

fn same_point(a: [f64; 2], b: [f64; 2]) -> bool {
    same_distance(a[0], b[0]) && same_distance(a[1], b[1])
}

fn args<'a>(
    element: &'a Element,
    elements_map: &'a ElementsMap<'a>,
    point: [f64; 2],
    threshold: f64,
) -> HitTestArgs<'a> {
    HitTestArgs {
        point,
        element,
        threshold,
        elements_map,
        frame_name_bound: None,
        override_should_test_inside: false,
    }
}

// -- fixture replay ------------------------------------------------------------

#[test]
fn fixture_covers_every_entry_point_and_element_type() {
    let cases = cases();
    let kinds: HashSet<&str> = cases.iter().map(|c| c["kind"].as_str().expect("kind")).collect();
    for kind in ["probe", "intersect", "binding", "inside"] {
        assert!(kinds.contains(kind), "no {kind} case");
    }
    let types: HashSet<String> = cases
        .iter()
        .filter(|c| c["kind"] == "probe")
        .flat_map(|c| {
            elements(c)
                .into_iter()
                .map(|e| e.kind.element_type().as_str().to_string())
        })
        .collect();
    for t in [
        "rectangle", "diamond", "ellipse", "text", "image", "frame", "magicframe", "iframe",
        "embeddable", "stickynote", "line", "arrow", "freedraw",
    ] {
        assert!(types.contains(t), "no probe of a {t}");
    }
    let upstream = cases
        .iter()
        .filter(|c| c["id"].as_str().expect("id").starts_with("upstream-"))
        .count();
    assert!(upstream >= 40, "collision.test.tsx scenes: {upstream}");
}

#[test]
fn probes_match_upstream() {
    let mut failures = Vec::new();
    let mut probes = 0;
    // one cache shared across every probe, as the editor holds one: a
    // correct cache never changes an answer
    let mut shared = HitTestCache::new();
    for case in cases().iter().filter(|c| c["kind"] == "probe") {
        let id = case["id"].as_str().expect("id");
        let scene = elements(case);
        let map = ElementsMap::new(scene.iter());
        let target = by_id(&scene, case["target"].as_str().expect("target"));
        for (n, p) in case["probes"].as_array().expect("probes").iter().enumerate() {
            probes += 1;
            let at = point(&p["point"]);
            let threshold = number(&p["threshold"]);
            let hit_args = HitTestArgs {
                point: at,
                element: target,
                threshold,
                elements_map: &map,
                frame_name_bound: frame_name_bound(&p["frameNameBound"]),
                override_should_test_inside: p["overrideShouldTestInside"] == true,
            };
            let mut check = |what: &str, ok: bool, got: String, want: &Value| {
                if !ok {
                    failures.push(format!("{id} probe {n} {what}: got {got}, upstream {want}"));
                }
            };
            let fresh = hit_element_itself(&mut HitTestCache::new(), &hit_args);
            check("hit", Value::Bool(fresh) == p["hit"], fresh.to_string(), &p["hit"]);
            let cached = hit_element_itself(&mut shared, &hit_args);
            check("hit (shared cache)", Value::Bool(cached) == p["hit"], cached.to_string(), &p["hit"]);
            let distance = distance_to_element(target, &map, at);
            check(
                "distance",
                same_distance(distance, number(&p["distance"])),
                distance.to_string(),
                &p["distance"],
            );
            let inside = is_point_in_element(at, target, &map);
            check("inside", Value::Bool(inside) == p["inside"], inside.to_string(), &p["inside"]);
            let sti = should_test_inside(target);
            check(
                "shouldTestInside",
                Value::Bool(sti) == p["shouldTestInside"],
                sti.to_string(),
                &p["shouldTestInside"],
            );
            let bb = hit_element_bounding_box(at, target, &map, threshold);
            check("boundingBox", Value::Bool(bb) == p["boundingBox"], bb.to_string(), &p["boundingBox"]);
            let bt = hit_element_bound_text(at, target, &map);
            check("boundText", Value::Bool(bt) == p["boundText"], bt.to_string(), &p["boundText"]);
            let bbo = hit_element_bounding_box_only(&mut HitTestCache::new(), &hit_args, &map);
            check(
                "boundingBoxOnly",
                Value::Bool(bbo) == p["boundingBoxOnly"],
                bbo.to_string(),
                &p["boundingBoxOnly"],
            );
        }
    }
    assert!(probes > 2000, "{probes} probes");
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn intersections_match_upstream() {
    let mut failures = Vec::new();
    for case in cases().iter().filter(|c| c["kind"] == "intersect") {
        let id = case["id"].as_str().expect("id");
        let scene = elements(case);
        let map = ElementsMap::new(scene.iter());
        let target = by_id(&scene, case["target"].as_str().expect("target"));
        for (n, s) in case["segments"].as_array().expect("segments").iter().enumerate() {
            let segment = [point(&s["segment"][0]), point(&s["segment"][1])];
            let got = intersect_element_with_line_segment(
                target,
                &map,
                segment,
                number(&s["offset"]),
                s["onlyFirst"] == true,
            );
            let want: Vec<[f64; 2]> = s["result"].as_array().expect("result").iter().map(point).collect();
            if got.len() != want.len() || got.iter().zip(&want).any(|(a, b)| !same_point(*a, *b)) {
                failures.push(format!("{id} segment {n}: got {got:?}, upstream {want:?}"));
            }
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn binding_hit_tests_match_upstream() {
    let mut failures = Vec::new();
    for case in cases().iter().filter(|c| c["kind"] == "binding") {
        let id = case["id"].as_str().expect("id");
        let scene = elements(case);
        let refs: Vec<&Element> = scene.iter().collect();
        let map = ElementsMap::new(scene.iter());
        for (n, p) in case["points"].as_array().expect("points").iter().enumerate() {
            let at = point(&p["point"]);
            let zoom = number(&p["zoom"]);
            let hovered = get_hovered_element_for_binding(at, &refs, &map, zoom).map(|e| e.base.id.clone());
            let want_hovered = p["hovered"].as_str().map(str::to_string);
            if hovered != want_hovered {
                failures.push(format!("{id} point {n} hovered: got {hovered:?}, upstream {want_hovered:?}"));
            }
            let all: Vec<String> = get_all_hovered_element_at_point(at, &refs, &map, zoom)
                .into_iter()
                .map(|e| e.base.id.clone())
                .collect();
            let want_all: Vec<String> = p["all"]
                .as_array()
                .expect("all")
                .iter()
                .map(|v| v.as_str().expect("id").to_string())
                .collect();
            if all != want_all {
                failures.push(format!("{id} point {n} all: got {all:?}, upstream {want_all:?}"));
            }
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn containment_matches_upstream() {
    let mut failures = Vec::new();
    for case in cases().iter().filter(|c| c["kind"] == "inside") {
        let id = case["id"].as_str().expect("id");
        let scene = elements(case);
        let map = ElementsMap::new(scene.iter());
        for (n, p) in case["pairs"].as_array().expect("pairs").iter().enumerate() {
            let inner = by_id(&scene, p["inner"].as_str().expect("inner"));
            let outer = by_id(&scene, p["outer"].as_str().expect("outer"));
            let got = is_bindable_element_inside_other_bindable(inner, outer, &map);
            if Value::Bool(got) != p["result"] {
                failures.push(format!("{id} pair {n}: got {got}, upstream {}", p["result"]));
            }
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}

// -- App.getElementHitThreshold (App.tsx:6927-6934) ----------------------------

#[test]
fn hit_threshold_is_the_larger_of_half_the_stroke_and_the_zoomed_collision_threshold() {
    // DEFAULT_COLLISION_THRESHOLD = 2 * SIDE_RESIZING_THRESHOLD - EPSILON
    // (constants.ts:277-284) = 2 * (2 * 2) - 0.00001
    assert_eq!(DEFAULT_COLLISION_THRESHOLD, 2.0 * 4.0 - 1e-5);
    assert_eq!(DEFAULT_COLLISION_THRESHOLD, 7.99999);
    // max(sw / 2 + 0.1, 0.85 * (8 - 1e-5) / zoom)
    for &(sw, zoom) in &[(1.0, 1.0), (2.0, 1.0), (4.0, 0.1), (2.0, 30.0), (40.0, 1.0), (1.0, 10.0)] {
        let expected = f64::max(sw / 2.0 + 0.1, 0.85 * (DEFAULT_COLLISION_THRESHOLD / zoom));
        assert_eq!(get_element_hit_threshold(sw, zoom), expected, "sw {sw} zoom {zoom}");
    }
    assert_eq!(get_element_hit_threshold(2.0, 1.0), 0.85 * 7.99999);
    // thick strokes win at high zoom
    assert_eq!(get_element_hit_threshold(4.0, 30.0), 2.1);
    assert_eq!(get_element_hit_threshold(40.0, 1.0), 20.1);
}

// -- collision.test.tsx --------------------------------------------------------

fn hit(case_id: &str, target: Option<&str>, at: [f64; 2], threshold: f64) -> bool {
    let c = case(case_id);
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let target = by_id(&scene, target.unwrap_or_else(|| c["target"].as_str().expect("target")));
    hit_element_itself(&mut HitTestCache::new(), &args(target, &map, at, threshold))
}

fn distance(case_id: &str, at: [f64; 2]) -> f64 {
    let c = case(case_id);
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let target = by_id(&scene, c["target"].as_str().expect("target"));
    distance_to_element(target, &map, at)
}

fn inside(case_id: &str, at: [f64; 2]) -> bool {
    let c = case(case_id);
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let target = by_id(&scene, c["target"].as_str().expect("target"));
    is_point_in_element(at, target, &map)
}

fn rotate(p: [f64; 2], c: [f64; 2], angle: f64) -> [f64; 2] {
    let (s, co) = angle.sin_cos();
    [
        (p[0] - c[0]) * co - (p[1] - c[1]) * s + c[0],
        (p[0] - c[0]) * s + (p[1] - c[1]) * co + c[1],
    ]
}

#[test]
fn rotated_arrow_can_be_hit() {
    assert!(hit("upstream-rotated-arrow", None, [88.0, -68.0], 10.0));
}

#[test]
fn cache_reuses_a_hit_when_the_threshold_increases() {
    let c = case("upstream-cache-filled-rectangle");
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let mut cache = HitTestCache::new();
    let at = [100.5, 50.0];
    assert!(hit_element_itself(&mut cache, &args(&scene[0], &map, at, 1.0)));
    assert_eq!(cache.outline_tests(), 1);
    assert!(hit_element_itself(&mut cache, &args(&scene[0], &map, at, 10.0)));
    assert_eq!(cache.outline_tests(), 1);
}

#[test]
fn cache_is_not_reused_when_the_threshold_decreases() {
    let c = case("upstream-cache-transparent-rectangle");
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let mut cache = HitTestCache::new();
    let at = [105.0, 50.0];
    assert!(hit_element_itself(&mut cache, &args(&scene[0], &map, at, 10.0)));
    assert_eq!(cache.outline_tests(), 1);
    assert!(hit_element_itself(&mut cache, &args(&scene[0], &map, at, 6.0)));
    assert_eq!(cache.outline_tests(), 2);
}

#[test]
fn cache_is_not_reused_for_a_larger_threshold_after_a_miss() {
    let c = case("upstream-cache-transparent-rectangle");
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let mut cache = HitTestCache::new();
    let at = [105.0, 50.0];
    assert!(!hit_element_itself(&mut cache, &args(&scene[0], &map, at, 4.0)));
    assert_eq!(cache.outline_tests(), 1);
    // a smaller threshold can only miss too
    assert!(!hit_element_itself(&mut cache, &args(&scene[0], &map, at, 3.0)));
    assert_eq!(cache.outline_tests(), 1);
    assert!(hit_element_itself(&mut cache, &args(&scene[0], &map, at, 6.0)));
    assert_eq!(cache.outline_tests(), 2);
}

#[test]
fn cache_is_invalidated_when_the_element_version_changes() {
    let c = case("upstream-cache-filled-rectangle");
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let mut cache = HitTestCache::new();
    let at = [100.5, 50.0];
    assert!(hit_element_itself(&mut cache, &args(&scene[0], &map, at, 1.0)));
    assert_eq!(cache.outline_tests(), 1);
    let mut moved = scene[0].clone();
    moved.base.version += 1.0;
    moved.base.version_nonce += 1.0;
    assert!(hit_element_itself(&mut cache, &args(&moved, &map, at, 1.0)));
    assert_eq!(cache.outline_tests(), 2);
}

#[test]
fn override_should_test_inside_does_not_affect_caching() {
    let c = case("upstream-cache-transparent-rectangle");
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let mut cache = HitTestCache::new();
    let at = [50.0, 50.0];
    assert!(!hit_element_itself(&mut cache, &args(&scene[0], &map, at, 10.0)));
    assert_eq!(cache.outline_tests(), 1);
    let overridden = HitTestArgs {
        override_should_test_inside: true,
        ..args(&scene[0], &map, at, 10.0)
    };
    assert!(hit_element_itself(&mut cache, &overridden));
}

#[test]
fn cache_rechecks_a_bound_label_when_only_its_arrow_changes() {
    // the scene before and after API.updateElement(arrow, { x: 500 }): the
    // label keeps its version, so the cache must not answer for it
    let before = case("upstream-cache-bound-label-before");
    let after = case("upstream-cache-bound-label-after");
    let before_scene = elements(&before);
    let after_scene = elements(&after);
    let label_id = before["target"].as_str().expect("target");
    let label_before = by_id(&before_scene, label_id);
    let label_after = by_id(&after_scene, label_id);
    assert_eq!(label_before.base.version, label_after.base.version);
    assert_eq!(label_before.base.version_nonce, label_after.base.version_nonce);

    let mut cache = HitTestCache::new();
    let before_map = ElementsMap::new(before_scene.iter());
    let after_map = ElementsMap::new(after_scene.iter());
    assert!(hit_element_itself(&mut cache, &args(label_before, &before_map, [350.0, 200.0], 1.0)));
    assert!(!hit_element_itself(&mut cache, &args(label_after, &after_map, [350.0, 200.0], 1.0)));
    assert!(hit_element_itself(&mut cache, &args(label_after, &after_map, [650.0, 200.0], 1.0)));
}

const VARIABLE: &str = "upstream-freedraw-straight-variable";
const CONSTANT: &str = "upstream-freedraw-straight-constant";

#[test]
fn freedraw_centerline_is_a_direct_hit_for_both_modes() {
    assert_eq!(distance(VARIABLE, [50.0, 0.0]), 0.0);
    assert_eq!(distance(CONSTANT, [50.0, 0.0]), 0.0);
}

#[test]
fn freedraw_hits_across_the_body_of_a_thick_stroke() {
    assert_eq!(distance(VARIABLE, [50.0, 20.0]), 0.0);
}

#[test]
fn freedraw_variable_width_has_a_wider_hit_area_than_constant() {
    let variable = distance(VARIABLE, [50.0, 20.0]);
    let constant = distance(CONSTANT, [50.0, 20.0]);
    assert_eq!(variable, 0.0);
    assert!(constant > 0.0);
    assert!(variable < constant);
}

#[test]
fn freedraw_misses_points_outside_the_widest_stroke() {
    assert!(distance(VARIABLE, [50.0, 45.0]) > 0.0);
}

#[test]
fn freedraw_hits_thick_ink_outside_the_centerline_bounds() {
    assert!(hit(VARIABLE, None, [50.0, 20.0], 1.0));
    assert!(hit(VARIABLE, None, [50.0, -20.0], 1.0));
    assert!(hit(CONSTANT, None, [50.0, 10.0], 1.0));
    assert!(!hit(CONSTANT, None, [50.0, 20.0], 1.0));
    assert!(!hit(VARIABLE, None, [50.0, 45.0], 1.0));
}

#[test]
fn freedraw_hits_the_start_cap_of_a_short_stroke() {
    let id = "upstream-freedraw-short-start-cap";
    assert_eq!(distance(id, [0.1, 4.9]), 0.0);
    // the hit threshold at 30x zoom
    assert!(hit(id, None, [0.1, 4.9], 0.6));
}

#[test]
fn freedraw_loop_fill_is_hit_independently_of_the_stroke() {
    for variability in ["variable", "constant"] {
        for (name, angle) in [("0", 0.0), ("quarter-pi", std::f64::consts::FRAC_PI_4)] {
            let filled = format!("upstream-freedraw-loop-{variability}-{name}-filled");
            let transparent = format!("upstream-freedraw-loop-{variability}-{name}-transparent");
            let p = rotate([400.0, 250.0], [380.0, 240.0], angle);
            assert!(distance(&filled, p) > 10.0, "{filled}");
            assert!(inside(&filled, p), "{filled}");
            assert!(hit(&filled, None, p, 1.0), "{filled}");
            assert!(distance(&filled, p) > 10.0, "{filled}");
            // a transparent loop's interior is not hit
            assert!(inside(&transparent, p), "{transparent}");
            assert!(!hit(&transparent, None, p, 1.0), "{transparent}");
            // the empty corners of the loop's bounds are not fill
            if angle == 0.0 {
                assert!(!inside(&filled, [310.0, 210.0]), "{filled}");
                assert!(!hit(&filled, None, [310.0, 210.0], 1.0), "{filled}");
            }
        }
    }
}

#[test]
fn freedraw_loop_fill_contains_the_centre_and_axes() {
    for (name, angle) in [("0", 0.0), ("quarter-pi", std::f64::consts::FRAC_PI_4)] {
        let id = format!("upstream-freedraw-loop-variable-{name}-filled");
        let center = [380.0, 240.0];
        for p in [center, [400.0, 240.0], [380.0, 250.0]] {
            assert!(inside(&id, rotate(p, center, angle)), "{id} {p:?}");
        }
    }
}

#[test]
fn freedraw_loop_fill_closes_an_unsnapped_loop() {
    assert!(inside("upstream-freedraw-loop-unsnapped-0", [440.0, 239.5]));
    let p = rotate([440.0, 239.5], [380.0, 240.0], std::f64::consts::FRAC_PI_4);
    assert!(inside("upstream-freedraw-loop-unsnapped-quarter-pi", p));
}

#[test]
fn freedraw_loop_rotates_about_the_unrotated_bounds_centre() {
    let p = rotate([330.0, 205.0], [400.0, 250.0], std::f64::consts::FRAC_PI_4);
    assert!(inside("upstream-freedraw-asymmetric-loop", p));
}

#[test]
fn freedraw_hits_smoothed_fill_outside_the_rotated_point_bounds() {
    let id = "upstream-freedraw-smoothed-fill-outside-bounds";
    let c = case(id);
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let p = rotate([436.0, 240.0], [400.0, 250.0], 2.0 * std::f64::consts::PI / 3.0);
    let [x1, y1, x2, y2] = get_element_bounds(&scene[0], &map);
    assert!(p[0] < x1 || p[0] > x2 || p[1] < y1 || p[1] > y2);
    assert!(inside(id, p));
    assert!(hit(id, None, p, 1.0));
}

#[test]
fn freedraw_degenerate_loops_contain_nothing() {
    assert!(!inside("upstream-freedraw-retraced", [350.0, 250.0]));
    assert!(!inside("upstream-freedraw-two-identical-points", [300.15, 200.15]));
}

#[test]
fn freedraw_nearly_closed_path_keeps_its_curved_fill() {
    assert!(inside("upstream-freedraw-nearly-closed-three-points", [350.0, 250.0]));
    assert!(inside("upstream-freedraw-smoothed-beyond-raw-polygon", [305.0, 285.0]));
}

#[test]
fn freedraw_self_intersecting_loop_is_even_odd() {
    assert!(!inside("upstream-freedraw-self-intersecting", [400.0, 300.0]));
}

#[test]
fn freedraw_fill_follows_changed_points() {
    assert!(inside("upstream-freedraw-loop-variable-0-filled", [415.0, 255.0]));
    assert!(!inside("upstream-freedraw-points-changed", [415.0, 255.0]));
}

#[test]
fn transparent_ellipse_outline_is_not_hit_from_its_centre_line() {
    assert!(!hit("upstream-ellipse-center-line", None, [210.0, 50.0], 10.0));
}

#[test]
fn rounded_diamond_corner_is_hit_through_its_apex() {
    let c = case("upstream-intersect-rounded-diamond");
    let scene = elements(&c);
    let map = ElementsMap::new(scene.iter());
    let s = &c["segments"][0];
    let segment = [point(&s["segment"][0]), point(&s["segment"][1])];
    let left = point(&c["leftMidpoint"]);
    assert_eq!(segment, [[200.0, left[1]], [-200.0, left[1]]]);
    let hits = intersect_element_with_line_segment(&scene[0], &map, segment, 6.0, false);
    assert!(!hits.is_empty());
    // toBeCloseTo(left[0] - 6, 0) and toBeCloseTo(left[1])
    assert!((hits[0][0] - (left[0] - 6.0)).abs() < 0.5, "{hits:?}");
    assert!((hits[0][1] - left[1]).abs() < 0.005, "{hits:?}");
}

fn binding(case_id: &str, at: [f64; 2], zoom: f64) -> (Option<String>, Vec<String>) {
    let c = case(case_id);
    let scene = elements(&c);
    let refs: Vec<&Element> = scene.iter().collect();
    let map = ElementsMap::new(scene.iter());
    (
        get_hovered_element_for_binding(at, &refs, &map, zoom).map(|e| e.base.id.clone()),
        get_all_hovered_element_at_point(at, &refs, &map, zoom)
            .into_iter()
            .map(|e| e.base.id.clone())
            .collect(),
    )
}

fn ids(ids: &[&str]) -> Vec<String> {
    ids.iter().map(|s| s.to_string()).collect()
}

#[test]
fn binding_uses_the_zoom_aware_binding_distance() {
    // 20px outside the right edge: 15px binding distance at zoom 1, 25px at 0.4
    assert_eq!(binding("upstream-binding-zoom", [120.0, 50.0], 1.0), (None, vec![]));
    assert_eq!(
        binding("upstream-binding-zoom", [120.0, 50.0], 0.4),
        (Some("rect".into()), ids(&["rect"]))
    );
}

#[test]
fn binding_skips_elements_hidden_behind_an_opaque_element() {
    assert_eq!(
        binding("upstream-binding-cover-opaque", [50.0, 50.0], 1.0),
        (Some("cover".into()), ids(&["cover"]))
    );
    assert_eq!(
        binding("upstream-binding-cover-transparent", [50.0, 50.0], 1.0),
        (Some("hidden".into()), ids(&["cover", "hidden"]))
    );
}

#[test]
fn binding_is_hidden_by_an_image_and_a_locked_opaque_element() {
    assert_eq!(
        binding("upstream-binding-image", [50.0, 50.0], 1.0),
        (Some("image".into()), ids(&["image"]))
    );
    assert_eq!(binding("upstream-binding-locked-opaque", [50.0, 50.0], 1.0), (None, vec![]));
    assert_eq!(
        binding("upstream-binding-locked-transparent", [50.0, 50.0], 1.0),
        (Some("hidden".into()), ids(&["hidden"]))
    );
}

#[test]
fn binding_prefers_the_container_edge_next_to_a_nested_element() {
    assert_eq!(binding("upstream-binding-nested", [5.0, 100.0], 1.0).0.as_deref(), Some("container"));
    assert_eq!(binding("upstream-binding-nested", [10.0, 100.0], 1.0).0.as_deref(), Some("child"));
}

#[test]
fn binding_prefers_a_smaller_element_straddling_the_edge_when_inside_both() {
    assert_eq!(binding("upstream-binding-badge", [3.0, 92.0], 1.0).0.as_deref(), Some("badge"));
    assert_eq!(binding("upstream-binding-badge", [-5.0, 108.0], 1.0).0.as_deref(), Some("container"));
}

#[test]
fn binding_at_a_circle_centre() {
    assert_eq!(
        binding("upstream-binding-circle-transparent", [100.0, 100.0], 1.0).0.as_deref(),
        Some("circle")
    );
    assert_eq!(
        binding("upstream-binding-circle-opaque", [100.0, 100.0], 1.0),
        (Some("circle".into()), ids(&["circle"]))
    );
}
